package com.gasczoology.invertebratelab.data

/** Qualitative teaching coordinates, never pH, concentrations or measured biological seconds. */
data class DigestiveMaturationPose(val acidification: Float, val enzymeDelivery: Float,
    val breakdown: Float, val soluteUptake: Float)

object ParameciumDigestiveMaturation {
    private fun b(en: String, ta: String) = BilingualText(en, ta)
    fun pose(stage: String, phase: Float): DigestiveMaturationPose {
        val p = phase.coerceIn(0f, 1f)
        return when(stage) {
            "acidification" -> DigestiveMaturationPose(p, 0f, 0f, 0f)
            "digestion" -> DigestiveMaturationPose(1f, p, ((p-.35f)/.65f).coerceIn(0f,1f), 0f)
            "uptake" -> DigestiveMaturationPose(1f, 1f, 1f, p)
            else -> DigestiveMaturationPose(0f, 0f, 0f, 0f)
        }
    }
    val structures = listOf(
        NutritionStructure("acidosome", b("A · Acidosome", "A · அமிலச் சிறுகுமிழ் (acidosome)"), b(
            "Acidosomes are acidic vesicles distinguished experimentally from lysosomes. Allen and Fok found that they lacked the tested acid-phosphatase activity and fused with newly released digestive vacuoles before lysosomal fusion. A and L are different teaching symbols, not interchangeable organelles; their drawn sizes and contents are not ultrastructural measurements.",
            "அமிலச் சிறுகுமிழ்கள், சோதனை வழியாக லைசோசோம்களிலிருந்து வேறுபடுத்தப்பட்ட அமிலமுள்ள சிறுகுமிழ்கள். Allen மற்றும் Fok ஆய்வில் சோதித்த அமில பாஸ்பட்டேஸ் செயற்பாடு இவற்றில் இல்லை; லைசோசோம் இணைவிற்கு முன் புதிதாகப் பிரிந்த உணவு நுண்குமிழ்களுடன் இவை இணைந்தன. A மற்றும் L வெவ்வேறு கற்பித்தல் குறிகள்; ஒன்றுக்கொன்று மாற்றான நுண்ணுறுப்புகள் அல்ல. வரைந்த அளவும் உள்ளடக்கமும் நுண்ணமைப்பு அளவீடுகள் அல்ல.")),
        NutritionStructure("lysosome", b("L · Lysosome and hydrolase delivery", "L · லைசோசோமும் நீராற்பகுப்பு நொதி வழங்கலும்"), b(
            "Lysosomal fusion supplies digestive hydrolases to the food-vacuole lumen. Enzyme-mediated breakdown follows a maturation sequence; an acid colour alone cannot demonstrate proteolysis. The dotted L contents denote delivery of enzymes, not resolved individual protein molecules or a counted number of lysosomes.",
            "லைசோசோம் இணைவு உணவு நுண்குமிழின் உட்குழிக்குச் செரிமான நீராற்பகுப்பு நொதிகளை வழங்குகிறது. நொதி வழிச் சிதைவு முதிர்வு வரிசையைச் சார்ந்தது; அமிலத்தைக் குறிக்கும் நிறம் மட்டும் புரதச் சிதைவை நிரூபிக்காது. L இல் உள்ள புள்ளிகள் நொதி வழங்கலைக் குறிக்கின்றன; தனிப் புரத மூலக்கூறுகளின் நேரடிக் காட்சியோ எண்ணிய லைசோசோம் தொகையோ அல்ல.")),
        NutritionStructure("vacuole-membrane", b("B · Vacuolar boundary", "B · உணவு நுண்குமிழ்ச் சவ்வு எல்லை"), b(
            "The membrane separates the digestive lumen from the cytosol. Fusion, retrieval and transport change the compartment without depositing whole prey loose in the cytoplasm. The double pencil contour is a boundary symbol, not a measured membrane thickness or a second epithelial wall.",
            "சவ்வு, செரிமான உட்குழியையும் சைட்டோசாலையும் பிரிக்கிறது. இணைவு, மீட்பு, கடத்தல் ஆகியவை முழு உணவுயிரியைச் சைட்டோபிளாஸ்மத்தில் சிதறவிடாமல் இப்பகுதியை மாற்றுகின்றன. இரட்டைப் பென்சில் கோடு ஒரு எல்லைக் குறியே; அளவிட்ட சவ்வுத் தடிமனோ இரண்டாவது புறச்செல் சுவரோ அல்ல. சவ்வைக் கடக்கும் ஊட்டச்சத்து விளைபொருள்களையும் சவ்வுக்குள் மீதமுள்ள உணவெச்சத்தையும் தனித்தறிய வேண்டும்.")),
        NutritionStructure("soluble-products", b("S · Soluble products and assimilation", "S · கரையும் விளைபொருள்களும் தன்மயமாக்கலும்"), b(
            "Small soluble products become available to cell metabolism after uptake across the vacuolar boundary. Absorption describes that transfer; assimilation describes subsequent incorporation into cellular material. Respiration can release energy from substrates. The small S dots indicate a conceptual transfer, not a species-specific transporter map.",
            "நுண்குமிழ்ச் சவ்வு வழி உறிஞ்சப்பட்ட சிறிய கரையக்கூடிய விளைபொருள்கள் செல் வளர்சிதை மாற்றத்திற்குக் கிடைக்கின்றன. இக்கடத்தலை உறிஞ்சல் என்றும், பின்னர் செல் பொருள்களில் சேர்த்தலைத் தன்மயமாக்கல் என்றும் கூறுகிறோம். சுவாசம் மூலம் மூலப்பொருளிலிருந்து ஆற்றல் பெறலாம். சிறிய S புள்ளிகள் கருத்தியல் கடத்தலைக் குறிக்கின்றன; இனத்திற்கான கடத்திப் புரத வரைபடம் அல்ல.")),
    )
    val readings = listOf(
        NutritionReading("5.3", b("5.3 · Early acidification: a distinct maturation step", "5.3 · தொடக்க அமிலமாதல்: தனி முதிர்வு நிலை"), listOf(b(
            "A newly released food vacuole does not instantly become a fully digestive compartment. Acidosomes interact with it early in maturation. Allen and Fok's 1983 experiments combined vital dyes, enzyme cytochemistry and electron microscopy: the vesicles were acidic, lacked the tested acid-phosphatase activity and fused before lysosomal delivery. These observations justify distinguishing acidosomes from digestive lysosomes.",
            "புதிதாகப் பிரிந்த உணவு நுண்குமிழ் உடனே முழுச் செரிமானப் பகுதியாக மாறுவதில்லை. முதிர்வின் தொடக்கத்தில் அமிலச் சிறுகுமிழ்கள் அதனுடன் தொடர்புகொள்கின்றன. Allen மற்றும் Fok இன் 1983 ஆய்வில் உயிர்ச்சாயம், நொதிச் செல்வேதியியல், மின்னணு நுண்ணோக்கி ஆகியவை இணைக்கப்பட்டன. சிறுகுமிழ்களில் அமிலம் இருந்தது; சோதித்த அமில பாஸ்பட்டேஸ் செயற்பாடு இல்லை; லைசோசோம் வழங்கலுக்கு முன் இணைந்தன. இச்சான்றுகள் அவற்றைச் செரிமான லைசோசோம்களிலிருந்து வேறுபடுத்த ஆதாரமாகின்றன."), b(
            "Acidification changes the environment experienced by swallowed organisms and helps prepare material for subsequent digestion. It must not be equated with completion of enzymatic hydrolysis, absorption or assimilation. Experimental perturbations can affect several membrane events simultaneously; a drug response alone is not a direct film of one molecular mechanism. The qualitative animation separates events to make their order intelligible.",
            "அமிலமாதல் உட்கொள்ளப்பட்ட உயிரிகள் எதிர்கொள்ளும் சூழலை மாற்றி, பின்னர் நடைபெறும் செரிமானத்திற்குப் பொருளைத் தயாரிக்க உதவுகிறது. அதை நொதி வழிச் சிதைவு, உறிஞ்சல் அல்லது தன்மயமாக்கல் முடிவுடன் ஒப்பிடக்கூடாது. சோதனை மாற்றங்கள் பல சவ்வு நிகழ்வுகளை ஒரே நேரத்தில் பாதிக்கலாம்; மருந்துக்கான பதில் மட்டும் ஒரு மூலக்கூறு இயங்குமுறையின் நேரடித் திரைப்படம் அல்ல. நிகழ்வுகளின் வரிசையைப் புரிய வைக்க இயக்கப்படம் அவற்றைத் தனித்துக் காட்டுகிறது."), b(
            "The A vesicle approaches and merges with the drawn vacuole; stippling then changes inside the lumen. This is an explanatory cue, not a pH indicator reading. No numerical pH, duration or universal colour scale is assigned. Published observations from P. multimicronucleatum are identified as comparative evidence; a genus-level mechanism does not establish identical kinetics in every Paramecium species or preparation.",
            "A சிறுகுமிழ் வரைந்த உணவு நுண்குமிழை அணுகி இணைகிறது; பின்னர் உட்குழியில் புள்ளிக் குறிகள் மாறுகின்றன. இது விளக்கக் குறியே; pH காட்டியின் அளவீடு அல்ல. எண் pH, கால அளவு அல்லது எல்லா ஆய்வுகளுக்கும் பொதுவான நிற அளவுகோல் தரப்படவில்லை. P. multimicronucleatum பார்வைகள் ஒப்பீட்டு ஆதாரமாகத் தனியாகக் குறிக்கப்படுகின்றன. பேரினத்தில் அறிந்த இயங்குமுறை ஒவ்வொரு இனத்திலும் தயாரிப்பிலும் ஒரே இயக்கவியல் இருப்பதை நிரூபிக்காது."))),
        NutritionReading("5.4", b("5.4 · Lysosomal fusion and intracellular digestion", "5.4 · லைசோசோம் இணைவும் செல்லுக்குள் செரிமானமும்"), listOf(b(
            "After early maturation, lysosomes bind and fuse with the digestive compartment, providing hydrolases that break down suitable food material. The resulting phagolysosomal phase differs from a newly formed phagosome. Proteins and other substrates are processed within a membrane-bounded lumen; enzyme activity and substrate susceptibility matter. Digestion is not the mechanical disappearance of a dot from a moving picture.",
            "தொடக்க முதிர்வுக்குப் பின் லைசோசோம்கள் செரிமானப் பகுதியுடன் பிணைந்து இணைகின்றன; ஏற்ற உணவுப் பொருளைச் சிதைக்கும் நீராற்பகுப்பு நொதிகளை வழங்குகின்றன. இவ்வாறு உருவாகும் phagolysosome நிலை, புதிதாக உருவான phagosome நிலையிலிருந்து வேறுபடுகிறது. புரதமும் பிற மூலப்பொருள்களும் சவ்வால் சூழப்பட்ட உட்குழிக்குள் செயலாக்கப்படுகின்றன; நொதிச் செயற்பாடும் மூலப்பொருளின் சிதைவுத்தன்மையும் முக்கியம். இயக்கப்படத்தில் ஒரு புள்ளி மறைவதே செரிமானம் அல்ல."), b(
            "In the L view a vesicle approaches, its boundary merges and enzyme cues appear within the vacuole before larger food cues fragment. The membrane continues to separate lumen and cytosol. This staged representation makes enzyme delivery and hydrolysis distinguishable, although real vacuoles overlap in age and activity. Multiple vacuoles in one living cell need not be synchronized to the same teaching stage.",
            "L காட்சியில் சிறுகுமிழ் அணுகுகிறது; அதன் எல்லை இணைகிறது; பெரிய உணவுக் குறிகள் துண்டாகும் முன் உட்குழியில் நொதிக் குறிகள் தோன்றுகின்றன. சவ்வு உட்குழியையும் சைட்டோசாலையும் தொடர்ந்து பிரிக்கிறது. நிலைப்படுத்திய விளக்கம் நொதி வழங்கலையும் நீராற்பகுப்பையும் வேறுபடுத்துகிறது. ஆனால் உயிருள்ள செல்லின் நுண்குமிழ்கள் வெவ்வேறு வயதும் செயல்பாடும் கொண்டிருக்கலாம். ஒரே செல்லின் அனைத்து நுண்குமிழ்களும் ஒரே கற்பித்தல் நிலையில் ஒத்திசைந்து இருக்க வேண்டியதில்லை."), b(
            "Timed cytochemistry and membrane studies in P. caudatum provide stronger support than shape alone for digestive maturation. Retrieval of lysosomal membrane and associated enzyme was documented after active digestion by Allen and Fok in 1984. Thus the vacuole is a changing membrane system, not a disposable bag that must burst. The diagram omits molecular transporters, individual enzyme identities and experimentally calibrated membrane areas.",
            "P. caudatum இல் காலப் பதிவு கொண்ட செல்வேதியியல் மற்றும் சவ்வு ஆய்வுகள், வடிவத்தை மட்டும் விட செரிமான முதிர்விற்கு வலுவான ஆதாரமளிக்கின்றன. செயற்பாட்டுச் செரிமானத்திற்குப் பின் லைசோசோம் சவ்வும் தொடர்புடைய நொதியும் மீட்கப்படுவதை Allen மற்றும் Fok 1984 இல் பதிவுசெய்தனர். எனவே நுண்குமிழ் மாறும் சவ்வுத் தொகுப்பே; வெடிக்க வேண்டிய ஒருமுறைப் பை அல்ல. மூலக்கூறு கடத்திகள், தனி நொதி அடையாளங்கள், அளவுத்திருத்திய சவ்வுப் பரப்புகள் படத்தில் விடப்பட்டுள்ளன."))),
        NutritionReading("5.5", b("5.5 · Absorption, assimilation and residual material", "5.5 · உறிஞ்சல், தன்மயமாக்கல் மற்றும் மீதமுள்ள பொருள்"), listOf(b(
            "Intracellular digestion makes soluble products available for uptake from the vacuolar lumen. Absorption is their transfer across the vacuolar boundary into the cell's metabolic pool. Assimilation is the subsequent use of nutrients to build or renew cellular material. Neither term means a whole bacterium passing freely through the membrane; the intact-particle cues that remain inside represent undigested residues.",
            "செல்லுக்குள் செரிமானம், நுண்குமிழ் உட்குழியிலிருந்து உறிஞ்சக்கூடிய கரையும் விளைபொருள்களை உருவாக்குகிறது. அவை நுண்குமிழ்ச் சவ்வைக் கடந்து செல்லின் வளர்சிதை மாற்றப் பொருள்தொகுப்பில் சேர்வதே உறிஞ்சல். ஊட்டச்சத்துகளைப் பயன்படுத்தி செல் பொருளை உருவாக்குதல் அல்லது புதுப்பித்தல் தன்மயமாக்கல் ஆகும். முழுப் பாக்டீரியா சவ்வைத் தடையின்றிக் கடப்பதாக இச்சொற்கள் பொருள்படாது. உள்ளே மீதமுள்ள துகள்குறிகள் செரிக்காத எச்சங்களைக் குறிக்கின்றன."), b(
            "Nutrient use includes biosynthesis and energy metabolism. A cell can take up material without incorporating all of it into new cell substance; some substrates are metabolized during respiration. Uptake, growth and respiration therefore require different observations or assays. Movement of a stained vacuole alone proves none of these chemical conversions, and nutritional yield cannot be inferred from an arbitrary animation speed.",
            "ஊட்டச்சத்து பயன்பாட்டில் உயிர்ப்பொருள் உருவாக்கமும் ஆற்றல் வளர்சிதை மாற்றமும் அடங்குகின்றன. உட்கொண்ட அனைத்தையும் புதிய செல் பொருளாக்காமல், சில மூலப்பொருள்களைச் சுவாசத்தின் போது செல் மாற்றலாம். எனவே உறிஞ்சல், வளர்ச்சி, சுவாசம் ஆகியவற்றுக்கு வெவ்வேறு கவனிப்புகள் அல்லது சோதனைகள் தேவை. சாயமிட்ட நுண்குமிழ் நகர்வது மட்டும் இவ்வேதி மாற்றங்களை நிரூபிக்காது; இயக்கப்பட வேகத்திலிருந்து ஊட்டப் பயனை ஊகிக்க முடியாது."), b(
            "The S view shows small product cues crossing the vacuolar boundary while larger residue cues remain enclosed. It is a conceptual account of transfer, not a catalogue of P. caudatum transporter proteins. Digestion and uptake may overlap biologically. Remaining undigested material is ultimately egested at the cytoproct; dissolved metabolic wastes and excess-water regulation must be taught separately rather than called the same excretory act.",
            "S காட்சியில் சிறிய விளைபொருள் குறிகள் நுண்குமிழ்ச் சவ்வைக் கடக்கின்றன; பெரிய எச்சக் குறிகள் உள்ளேயே இருக்கின்றன. இது கடத்தலின் கருத்தியல் விளக்கம்; P. caudatum கடத்திப் புரதங்களின் பட்டியல் அல்ல. செரிமானமும் உறிஞ்சலும் இயற்கையில் ஒன்றோடொன்று அமையலாம். மீதமுள்ள செரிக்காத பொருள் இறுதியில் சைட்டோப்ராக்ட் பகுதியில் வெளியேற்றப்படுகிறது. கரைந்த வளர்சிதை மாற்றக் கழிவுகளையும் மிகைநீர் ஒழுங்குபடுத்தலையும் ஒரே கழிவகற்றல் செயலாகக் கூறாமல் தனித்துக் கற்பிக்க வேண்டும்."))),
